from pathlib import Path
import re, base64, sys
root=Path(sys.argv[1] if len(sys.argv)>1 else 'extracted/EspritLibreAndroid')
htmlp=root/'app/src/main/assets/index.html'
html=htmlp.read_text(encoding='utf-8')
m=re.search(r'<img class="hello-logo" src="data:image/png;base64,([A-Za-z0-9+/=]+)"', html)
if not m: raise SystemExit('Logo not found')
res=root/'app/src/main/res/drawable'; res.mkdir(parents=True, exist_ok=True)
(res/'app_icon.png').write_bytes(base64.b64decode(m.group(1)))
old='function score(today){let s=82-today.length*8-thoughts.length*3-familyLoadPenalty();if(mood==="fatigue")s-=18;if(mood==="epuisee")s-=35;if(weather==="chaud")s-=7;if(s>74)return"🌱 Très serein";if(s>57)return"🌿 Serein";if(s>41)return"🍃 Équilibré";if(s>25)return"🍂 Chargé";return"🌪️ Sous pression"}'
new='''function computeSerenityScore(today){\n  let s=100;\n  const ev=today||[];\n  s-=Math.min(38,ev.length*5);\n  s-=Math.min(15,thoughts.length*2);\n  s-=Math.min(24,Math.round(familyLoadPenalty()*0.7));\n  const longEvents=ev.filter(e=>{const a=(e.start||"00:00").split(":").map(Number),b=(e.end||"00:00").split(":").map(Number);return (b[0]*60+b[1])-(a[0]*60+a[1])>=240}).length;\n  s-=Math.min(12,longEvents*4);\n  const lateEvents=ev.filter(e=>Number((e.start||"00:00").slice(0,2))>=19).length;\n  s-=Math.min(10,lateEvents*3);\n  if(mood==="fatigue")s-=12;\n  if(mood==="epuisee")s-=24;\n  if(weather==="chaud")s-=5;\n  if(floating.length>5)s-=Math.min(10,(floating.length-5)*2);\n  return Math.max(0,Math.min(100,Math.round(s)));\n}\nfunction score(today){const s=computeSerenityScore(today);if(s>=80)return"🌱 Très serein";if(s>=65)return"🌿 Serein";if(s>=50)return"🍃 Équilibré";if(s>=35)return"🍂 Chargé";return"🌪️ Sous pression"}'''
if old not in html: raise SystemExit('score function not found')
html=html.replace(old,new,1)
start=html.index('function runAiWeekLighten(){')
end=html.index('\nfunction aiCreateShoppingListFromPrompt', start)
ai='''function runAiWeekLighten(){\n  if(!isPremium){ alert("Cette fonction est disponible en Premium."); return; }\n  if(!aiConsentAllowed()){ alert("L’assistant IA n’est pas activé dans les consentements."); return; }\n  const card=document.getElementById("aiWeeklyResult");\n  const content=document.getElementById("aiWeeklyContent");\n  if(!card || !content)return;\n  const startW=weekStart(selectedDate);\n  const daysData=days.map((name,i)=>{\n    const date=addDays(startW,i); const ev=eventsForDate(date); let minutes=0,late=0,long=0;\n    ev.forEach(e=>{const a=(e.start||"00:00").split(":").map(Number),b=(e.end||"00:00").split(":").map(Number);const d=Math.max(0,(b[0]*60+b[1])-(a[0]*60+a[1]));minutes+=d;if(Number((e.start||"00:00").slice(0,2))>=19)late++;if(d>=240)long++;});\n    return {name,date,ev,minutes,late,long,score:computeSerenityScore(ev)};\n  });\n  const busiest=[...daysData].sort((a,b)=>b.minutes-a.minutes)[0];\n  const lightest=[...daysData].sort((a,b)=>a.minutes-b.minutes)[0];\n  const avg=Math.round(daysData.reduce((s,d)=>s+d.score,0)/daysData.length);\n  const suggestions=[];\n  suggestions.push(`🌿 Score de sérénité moyen estimé : ${avg}/100.`);\n  if(busiest && busiest.minutes>360) suggestions.push(`📆 ${busiest.name} est la journée la plus chargée (${Math.round(busiest.minutes/60*10)/10} h planifiées). Évite d’y ajouter une tâche importante.`);\n  if(lightest) suggestions.push(`🪶 ${lightest.name} est actuellement le jour le plus léger : bon candidat pour déplacer une tâche non urgente.`);\n  const lateTotal=daysData.reduce((s,d)=>s+d.late,0);\n  if(lateTotal>=2) suggestions.push(`🌙 ${lateTotal} activité(s) commencent après 19 h cette semaine. Garde au moins une soirée sans obligation si possible.`);\n  if(mood==="fatigue" || mood==="epuisee") suggestions.push("😴 Ton niveau de fatigue pèse dans le score : priorité au repos et aux tâches courtes avant d’ajouter de nouvelles contraintes.");\n  if(floating.length) suggestions.push(`🧩 ${floating.length} tâche(s) restent à placer. Répartis-les sur les journées au score le plus élevé plutôt que de les concentrer.`);\n  if(liveWeather){if(liveWeather.rain)suggestions.push("🌧️ La météo locale annonce de la pluie : privilégie les tâches intérieures ou regroupe les déplacements.");else if(liveWeather.temperature>=30)suggestions.push(`🔥 Il fait environ ${Math.round(liveWeather.temperature)}°C : réserve les activités extérieures au matin ou au soir.`);else suggestions.push(`☀️ Météo locale : environ ${Math.round(liveWeather.temperature)}°C. Les activités extérieures peuvent être placées sur les créneaux les moins chargés.`);}else suggestions.push("📍 Active la météo locale pour que l’assistant tienne compte des conditions réelles.");\n  if(avg>=75)suggestions.push("✅ Ta semaine reste globalement respirable : conserve des marges plutôt que de remplir tous les créneaux libres.");else if(avg<50)suggestions.push("⚠️ La semaine paraît lourde : déplace, délègue ou supprime au moins une tâche non essentielle.");\n  content.innerHTML=`<div class="ai-result"><b>Analyse de ta semaine</b><ul>${suggestions.map(s=>`<li>${s}</li>`).join("")}</ul><p class="note">Assistant intelligent local de développement : analyse automatique de tes données présentes dans l’application.</p></div>`;\n  card.classList.add("ai-visible");card.style.display="block";card.scrollIntoView({behavior:"smooth",block:"start"});\n}\n'''
html=html[:start]+ai+html[end:]
html=html.replace('const num=label.includes("Très")?88:label.includes("Serein")?78:label.includes("Équilibré")?62:label.includes("Chargé")?46:32;','const num=computeSerenityScore(today);',1)
htmlp.write_text(html,encoding='utf-8')
manifest=root/'app/src/main/AndroidManifest.xml'
s=manifest.read_text(); s=s.replace('android:label="@string/app_name"','android:label="@string/app_name"\n        android:icon="@drawable/app_icon"\n        android:roundIcon="@drawable/app_icon"'); manifest.write_text(s)
(root/'app/src/main/res/values/strings.xml').write_text("<resources><string name=\"app_name\">L\\'Esprit Léger</string></resources>\n")
java=root/'app/src/main/java/com/espritlibre/app/MainActivity.java'
java.write_text(r'''package com.espritlibre.app;
import android.Manifest;import android.annotation.SuppressLint;import android.app.Activity;import android.content.pm.PackageManager;import android.os.Bundle;import android.webkit.GeolocationPermissions;import android.webkit.PermissionRequest;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import java.io.BufferedReader;import java.io.InputStreamReader;
public class MainActivity extends Activity{
 private WebView webView;private static final int LOCATION_REQ=100;
 @SuppressLint("SetJavaScriptEnabled") @Override public void onCreate(Bundle b){super.onCreate(b);webView=new WebView(this);setContentView(webView);
  webView.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});webView.requestApplyInsets();
  WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_COMPATIBILITY_MODE);s.setCacheMode(WebSettings.LOAD_DEFAULT);
  webView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){super.onPageFinished(v,u);tryLoadWeather();}});
  webView.setWebChromeClient(new WebChromeClient(){@Override public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){boolean g=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;c.invoke(o,g,false);}@Override public void onPermissionRequest(PermissionRequest r){r.grant(r.getResources());}});
  try{BufferedReader r=new BufferedReader(new InputStreamReader(getAssets().open("index.html"),"UTF-8"));StringBuilder x=new StringBuilder();String l;while((l=r.readLine())!=null)x.append(l).append('\n');r.close();webView.loadDataWithBaseURL("https://appassets.androidplatform.net/",x.toString(),"text/html","UTF-8",null);}catch(Exception e){webView.loadUrl("file:///android_asset/index.html");}
  if(android.os.Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOCATION_REQ);
 }
 private void tryLoadWeather(){if(webView==null)return;boolean g=android.os.Build.VERSION.SDK_INT<23||checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;if(g)webView.postDelayed(()->webView.evaluateJavascript("if(typeof loadLiveWeather==='function'){loadLiveWeather();}",null),500);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOCATION_REQ)tryLoadWeather();}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
}
''',encoding='utf-8')
print('V6 patches applied')
